const fs = require('fs');
// 跨节点引用: cover_path/images/draft_dir 在 Prep TG + Cover 输出里
const p = $('Prep TG + Cover').first().json;
const files = [];
if (p.cover_path && fs.existsSync(p.cover_path)) files.push(p.cover_path);
for (const f of (p.images || [])) files.push(`${p.draft_dir}/${f}`);
return files.map((fp, i) => ({
  json: { filename: fp.split('/').pop(), filepath: fp, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token },
  binary: { data: { data: fs.readFileSync(fp).toString('base64'), mimeType: 'image/png', fileName: fp.split('/').pop() } }
}));

const fs = require('fs');
const http = require('http');
const raw = $input.first().json.choices[0].message.content;
let data = {};
for (let i = 0; i < 3; i++) {
  try { data = JSON.parse(raw); break; } catch (e) { const m = raw.match(/{[\s\S]*}/); if (m) raw = m[0]; else throw new Error('bad json from hauhau: ' + raw.slice(0,200)); }
}
const prev = $('Build Hauhau Prompt').item.json;

// 手动解析 url (沙箱无 URL 全局)
function parseUrl(url) {
  const m = url.match(/^https?:\/\/([^:\/]+)(?::(\d+))?([^?]*)/);
  if (!m) throw new Error('bad url: ' + url);
  return { hostname: m[1], port: m[2] ? parseInt(m[2]) : 80, path: m[3] || '/' };
}
function post(url, body, timeout) {
  return new Promise((res, rej) => {
    const u = parseUrl(url);
    const payload = JSON.stringify(body);
    const req = http.request({ hostname: u.hostname, port: u.port, path: u.path, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }, timeout: timeout||180000 }, r => {
      let d = ''; r.on('data', c => d += c); r.on('end', () => { try { res(JSON.parse(d)); } catch(e) { rej(e); } });
    });
    req.on('error', rej); req.on('timeout', () => { req.destroy(); rej(new Error('timeout')); });
    req.write(payload); req.end();
  });
}

async function verify(d) {
  const content = '标题: ' + (d.title||'') + '\n正文: ' + (d.body||'').slice(0, 900) + '\n标签: ' + (d.tags||[]).join(' ');
  const r = await post('http://127.0.0.1:8083/v1/chat/completions', {
    model: 'Qwen2.5-VL-7B', temperature: 0.1, max_tokens: 80, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: '你是小红书文案贴合度校验器。判断给定文案是否属于「家居家装/装修干货」垂类且贴合账号「宅有宅的道理」(中古风装修)。若核心是装修/软装/收纳/改造方法, 返回 {"fit":true,"reason":"..."}; 若偏到其他垂类(美妆/母婴/数码/穿搭/美食等), 返回 {"fit":false,"reason":"..."}。严格只返回JSON' },
      { role: 'user', content }
    ]
  });
  const c = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '{}';
  let p = {}; try { p = JSON.parse(c); } catch(e) { const m = c.match(/{[\s\S]*}/); if (m) { try { p = JSON.parse(m[0]); } catch(_) {} } }
  return { fit: p.fit === true, reason: (p.reason || '').slice(0, 200) };
}

let v = await verify(data);
let retried = false;
if (!v.fit) {
  retried = true;
  const retryPrompt = '上次生成的文案偏离了「家居家装/装修干货」垂类。' + v.reason + '\n请重新创作一篇严格围绕中古风装修/软装/收纳干货的文案, 保留: 标题15字内带emoji, 正文250-600字短句多段, 8-10个中文tag, ' + prev.num_images + '张配图英文prompt。\n上次文案(参考不要照抄): 标题=' + (data.title||'') + ' 正文=' + (data.body||'').slice(0,400) + '\n严格返回JSON {"title","body","tags","image_prompts"}';
  const rr = await post('http://127.0.0.1:8080/v1/chat/completions', {
    model: 'Qwen3.6-35B-Hauhau', temperature: 0.8, max_tokens: 9000, response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: '你是专业的小红书爆款文案师, 账号「宅有宅的道理」家居装修干货号, 主打中古风装修。严格返回JSON {"title","body","tags","image_prompts"}。正文不许出现#开头行, tag只在tags数组。' },
      { role: 'user', content: retryPrompt }
    ]
  }, 180000);
  const raw2 = (rr.choices && rr.choices[0].message.content) || '';
  let d2 = {}; for (let i = 0; i < 3; i++) { try { d2 = JSON.parse(raw2); break; } catch(e) { const m = raw2.match(/{[\s\S]*}/); if (m) raw2 = m[0]; else break; } }
  if (d2.title) { data = d2; v = await verify(d2); }
}
return [{ json: { ...prev, data, fit: v.fit, fit_reason: v.reason, retried } }];

const fs = require('fs');
const p = $input.first().json;
const d = p.data || {};
const body = (d.body || '').split('\n').filter(l => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const tagsClean = [...new Set((d.tags || []).map(t => t.replace(/^#+/, '').trim()).filter(Boolean))];
const ts = new Date().toISOString().slice(0,19).replace(/[-:T]/g,'');
const draftDir = `${p.drafts_root}/${ts}`;
fs.mkdirSync(draftDir, { recursive: true });
const md = `# ${d.title}\n\n${body}\n\n${tagsClean.map(t=>'#'+t).join(' ')}\n\n---\n_基于 ${p.hot_count} 篇热榜笔记提炼生成${p.retried ? ' (自动重写1次)' : ''}_\n`;
fs.writeFileSync(`${draftDir}/note.md`, md);
return [{ json: {
  draft_id: ts, draft_dir: draftDir, title: d.title, body: body, tags: tagsClean,
  image_prompts: d.image_prompts || [], num_images: p.num_images,
  hot_count: p.hot_count, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token,
  cover_url: p.cover_url, drafts_root: p.drafts_root,
  fit: p.fit, fit_reason: p.fit_reason, retried: p.retried
}}];

const p = $input.first().json;
const badge = p.retried ? ' [已自动重写]' : '';
return [{ json: { ...p,
  preview_text: '📝 文案草稿' + badge + ' (' + (p.fit ? '通过校验' : '可能偏题') + ')

' + p.title + '

' + (p.body||'').slice(0,300) + '...

' + (p.tags||[]).slice(0,8).map(t=>'#'+t).join(' ')
}}];

const fs = require('fs');
const http = require('http');
// Wait resume 后 $input 是 {ok, result} 包装, 从 A1 跨节点取真实数据
const p = $('A1 Prep Preview').item.json;
const decisionPath = `${p.draft_dir}/decision.json`;
let action = 'approve';
let reason = '';
try {
  if (fs.existsSync(decisionPath)) {
    const dec = JSON.parse(fs.readFileSync(decisionPath, 'utf8'));
    action = dec.action || 'approve';
    reason = dec.reason || '';
  }
} catch(e) { console.log('decision read err', e.message); }

let finalTitle = p.title, finalBody = p.body, finalTags = p.tags, finalPrompts = p.image_prompts || [];
let rewrote = false;
if (action === 'rewrite') {
  try {
    const payload = JSON.stringify({
      model: 'Qwen3.6-35B-Hauhau', temperature: 0.8, max_tokens: 9000, response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: '你是专业的小红书爆款文案师, 账号「宅有宅的道理」家居装修干货号, 主打中古风装修。严格返回JSON {"title","body","tags","image_prompts"}。正文不许出现#开头行, tag只在tags数组。' },
        { role: 'user', content: '用户要求重写这篇文案。' + reason + '\n请围绕中古风装修/软装/收纳干货重新创作, 标题15字内带emoji, 正文250-600字, 8-10个中文tag, ' + p.num_images + '张配图英文prompt。\n原稿(参考不要照抄): 标题=' + p.title + ' 正文=' + (p.body||'').slice(0,400) + '\n严格返回JSON {"title","body","tags","image_prompts"}' }
      ]
    });
    const rr = await new Promise((res, rej) => {
      const req = http.request({ hostname: '127.0.0.1', port: 8080, path: '/v1/chat/completions', method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }, timeout: 180000 }, r => {
        let d = ''; r.on('data', c => d += c); r.on('end', () => { try { res(JSON.parse(d)); } catch(e) { rej(e); } });
      });
      req.on('error', rej); req.on('timeout', () => { req.destroy(); rej(new Error('timeout')); });
      req.write(payload); req.end();
    });
    const raw2 = (rr.choices && rr.choices[0].message.content) || '';
    let d2 = {}; for (let i = 0; i < 3; i++) { try { d2 = JSON.parse(raw2); break; } catch(e) { const m = raw2.match(/{[\s\S]*}/); if (m) raw2 = m[0]; else break; } }
    if (d2.title) {
      finalTitle = d2.title; finalBody = (d2.body||'').split('\n').filter(l => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(l)).join('\n').replace(/\n{3,}/g,'\n\n').trim();
      finalTags = [...new Set((d2.tags||[]).map(t=>t.replace(/^#+/,'').trim()).filter(Boolean))];
      finalPrompts = d2.image_prompts || [];
      rewrote = true;
      const md = `# ${finalTitle}\n\n${finalBody}\n\n${finalTags.map(t=>'#'+t).join(' ')}\n\n---\n_用户要求重写 (${new Date().toISOString().slice(0,19)})_\n`;
      fs.writeFileSync(`${p.draft_dir}/note.md`, md);
    }
  } catch(e) { console.log('rewrite err', e.message); }
}

const n = Math.min(p.num_images, finalPrompts.length);
const result = [];
for (let i = 0; i < n; i++) {
  result.push({ json: { prompt: finalPrompts[i], index: i + 1, total: n, draft_dir: p.draft_dir, md_path: `${p.draft_dir}/note.md`, title: finalTitle, body: finalBody, tags: finalTags, hot_count: p.hot_count, tg_chat_id: p.tg_chat_id, tg_bot_token: p.tg_bot_token, cover_url: p.cover_url, draft_id: p.draft_id, decision: action, rewrote } });
}
return result;
